mapper.select:
SELECT page.*, , fi.info_id AS festival_info_id, fi.address, fi.event_place FROM ( SELECT ti.id, ti.title, ti.scope, ti.content_type, ti.category_id, ic.name AS category_name, ti.views, ti.created_at, period.start_date, period.end_date FROM travel_info ti JOIN info_categories ic ON ic.id = ti.category_id AND ic.is_visible = 1 JOIN festival_info festival ON festival.info_id = ti.id JOIN info_periods period ON period.info_id = ti.id WHERE ti.content_type = 'FESTIVAL'
AND period.id IN
#{id}
AND 1 = 0
) page JOIN festival_info fi ON fi.info_id = page.id

mapper.update:
UPDATE travel_info
SET structured_content = #{structuredContent}
WHERE id = #{id}
  AND content_format = 'STRUCTURED'

UPDATE travel_info
SET is_home_featured = #{homeFeatured},
    home_featured_order = #{homeFeaturedOrder}
WHERE id = #{id}

UPDATE info_images
SET is_thumbnail = 1
WHERE id = #{imageId}
  AND info_id = #{infoId}

mapper.delete:
DELETE FROM info_images
WHERE info_id = #{infoId}
  AND is_main = 1

