INSERT INTO travel_info_translations (
    travel_info_id, language_code, title, content, structured_text
) VALUES (
    #{travelInfoId}, #{languageCode}, #{title}, #{content}, #{structuredText}
)

mapper.update:
UPDATE travel_info_translations
SET title = #{title},
    content = #{content},
    structured_text = #{structuredText}
WHERE travel_info_id = #{travelInfoId}
  AND language_code = #{languageCode}

